export const ARCHITECTURES: readonly string[] = Object.freeze(['arm64', 'x64']);

/**
 * A toolchain cell this stage can name, with the Node line it declares.
 *
 * Every entry either restates a cell a frozen adapter publishes — the `id` and
 * the `nodeLine` are read from the adapter's own declaration, never retyped —
 * or is described from a measurement in `evidence/`, and says which.
 */
export type DescribedCell = Readonly<{
	id: string;
	lineage: Lineage;
	/** The Node line the cell declares, verbatim. */
	nodeLine: string;
	nodeMajor: number;
	/** Where this description comes from. */
	describedBy: string;
	/** Whether an adapter in this repository publishes the cell as a target. */
	published: boolean;
	/** What establishing this cell provides here, and what it does not. */
	provides: string;
}>;

/** The leading major of a version or range, or `null` when it reads as none. */
export function leadingMajor(value: string): number | null {
	let digits = '';
	let started = false;
	for (const character of value.trim()) {
		const code = character.charCodeAt(0);
		const isDigit = code >= 48 && code <= 57;
		if (isDigit) {
			started = true;
			digits += character;
			continue;
		}
		if (started) break;
		if (character === '^' || character === '~' || character === 'v' || character === '=')
			continue;
		if (character === '>' || character === '<' || character === ' ') continue;
		return null;
	}
	return digits === '' ? null : Number.parseInt(digits, 10);
}

function cellOfAdapterCell(cell: AngularTargetCell): DescribedCell | null {
	const major = leadingMajor(cell.nodeLine);
	if (major === null) return null;
	return Object.freeze({
		id: cell.id,
		lineage: 'angular' as const,
		nodeLine: cell.nodeLine,
		nodeMajor: major,
		describedBy: `published by the frozen Angular adapter as an AngularTargetCell; the Node line is the cell's own nodeLine declaration.`,
		published: true,
		provides:
			'the Node runtime the cell declares. The Angular packages the cell aligns a manifest to are written by the plan stage and resolved by the install stage, not by this one.',
	});
}

/**
 * The ngcc-bearing Angular 13 cell, described rather than published.
 *
 * `evidence/spikes/ngcc-1213-feasibility/verdict.json` measured it: all three
 * pre-Ivy libraries in the holdout are consumable at Angular 13.4.0 because
 * `@angular/compiler-cli` 13.4.0 still ships a real ngcc entry point, at the
 * price of holding rxjs at 6.x. No adapter in this repository publishes it, so
 * it is never the default for a lineage — `--cell` declares it, and this stage
 * then reads the Node line the spike recorded for it.
 */
export const NGCC_ANGULAR_13_CELL: DescribedCell = Object.freeze({
	id: 'angular-13.4.0',
	lineage: 'angular' as const,
	nodeLine: '16.20.2',
	nodeMajor: 16,
	describedBy:
		'described by evidence/spikes/ngcc-1213-feasibility/verdict.json, which names angular-13.4.0 the honest cell — @angular/compiler-cli 13.4.0 still ships a real ngcc bin and back-compiles the pre-Ivy libraries, and the cell Node runtime it recorded is v16.20.2. No adapter in this repository publishes this cell as a migration target.',
	published: false,
	provides:
		'the Node runtime the cell declares. The Angular 13 toolchain itself, and the rxjs 6 pin the spike recorded as its price, are not installed or written by this stage.',
});

